import{_ as t,o,c as d,ag as s}from"./chunks/framework.BZohXCq9.js";const m=JSON.parse('{"title":"Business Rules: Cancel, Refund, Complete Checkout, 3DS Payment & Payout","description":"","frontmatter":{},"headers":[],"relativePath":"BUSINESS_RULES_CANCEL_REFUND_PAYMENT_PAYOUT.md","filePath":"BUSINESS_RULES_CANCEL_REFUND_PAYMENT_PAYOUT.md"}'),n={name:"BUSINESS_RULES_CANCEL_REFUND_PAYMENT_PAYOUT.md"};function a(r,e,l,c,i,u){return o(),d("div",null,[...e[0]||(e[0]=[s('<h1 id="business-rules-cancel-refund-complete-checkout-3ds-payment-payout" tabindex="-1">Business Rules: Cancel, Refund, Complete Checkout, 3DS Payment &amp; Payout <a class="header-anchor" href="#business-rules-cancel-refund-complete-checkout-3ds-payment-payout" aria-label="Permalink to &quot;Business Rules: Cancel, Refund, Complete Checkout, 3DS Payment &amp; Payout&quot;">​</a></h1><p>This document describes the business rules and implementation for:</p><ul><li><strong>Cancel lesson</strong>: when cancellation is allowed and when it is blocked.</li><li><strong>Refund</strong>: when a student can request a refund and when admin can approve it.</li><li><strong>Complete checkout / incomplete checkouts</strong>: when a student can complete payment for a pending or T-48 booking.</li><li><strong>3DS / failed payment</strong>: when a student can complete 3DS or retry a failed payment for a slot.</li><li><strong>Payout</strong>: ensuring no double payout for the same lesson (race-condition safety).</li></ul><p>All of these rules were verified and implemented so that the system behaves consistently and safely.</p><hr><h2 id="_1-cancel-lesson" tabindex="-1">1. Cancel Lesson <a class="header-anchor" href="#_1-cancel-lesson" aria-label="Permalink to &quot;1. Cancel Lesson&quot;">​</a></h2><h3 id="rule" tabindex="-1">Rule <a class="header-anchor" href="#rule" aria-label="Permalink to &quot;Rule&quot;">​</a></h3><ul><li>A lesson can <strong>only</strong> be cancelled if: <ul><li>The slot is <strong>not</strong> already cancelled, and</li><li>The slot status is <strong>not</strong> completed, missed, or refund, and</li><li>The lesson date has <strong>not</strong> passed (cancellation only before the booking/slot date).</li></ul></li></ul><h3 id="implementation" tabindex="-1">Implementation <a class="header-anchor" href="#implementation" aria-label="Permalink to &quot;Implementation&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Layer</th><th>Location</th><th>What was done</th></tr></thead><tbody><tr><td>Backend</td><td><code>server/src/graphql/resolvers/studentBooking.resolver.js</code> → <code>cancelBookingSlot</code></td><td>After checking <code>status !== &quot;cancelled&quot;</code>, added a check: if <code>slot.status</code> is <code>&quot;completed&quot;</code>, <code>&quot;missed&quot;</code>, or <code>&quot;refund&quot;</code>, throw <code>UserInputError</code> with message <em>&quot;Cannot cancel: lesson is already completed, missed, or refunded.&quot;</em> Existing check for slot date in the past is unchanged.</td></tr><tr><td>Frontend</td><td><code>Frontend/src/pages/private/student-dashboard/bookingDetails.tsx</code></td><td>Introduced <code>cannotCancel</code>: <code>true</code> when <code>isLessonPast</code> <strong>or</strong> current slot status is <code>completed</code> / <code>missed</code> / <code>refund</code>. Cancel and Reschedule buttons are disabled when <code>cannotCancel</code>. Tooltips explain: <em>&quot;You can&#39;t cancel/reschedule: lesson is past or already completed/missed/refunded.&quot;</em></td></tr></tbody></table><hr><h2 id="_2-refund-request-approve" tabindex="-1">2. Refund (Request &amp; Approve) <a class="header-anchor" href="#_2-refund-request-approve" aria-label="Permalink to &quot;2. Refund (Request &amp; Approve)&quot;">​</a></h2><h3 id="rules" tabindex="-1">Rules <a class="header-anchor" href="#rules" aria-label="Permalink to &quot;Rules&quot;">​</a></h3><ul><li><p><strong>Request refund (student)</strong></p><ul><li>Only for <strong>cancelled</strong> lessons.</li><li><strong>Not</strong> allowed if the lesson date has already passed.</li><li>(Existing: not allowed if already paid out, already refunded, or no payment.)</li></ul></li><li><p><strong>Approve refund (admin)</strong></p><ul><li><strong>Not</strong> allowed if the lesson date has passed.</li><li><strong>Not</strong> allowed if the slot has been marked <strong>completed</strong> or <strong>missed</strong> (data integrity).</li></ul></li></ul><h3 id="implementation-1" tabindex="-1">Implementation <a class="header-anchor" href="#implementation-1" aria-label="Permalink to &quot;Implementation&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Layer</th><th>Location</th><th>What was done</th></tr></thead><tbody><tr><td>Backend</td><td><code>server/src/graphql/resolvers/refundRequest.resolver.js</code> → <code>requestRefund</code></td><td>Already enforced: only cancelled slots, and <code>slotEnd &lt;= new Date()</code> blocks with <em>&quot;Refund cannot be requested for lessons that have already passed.&quot;</em> No change.</td></tr><tr><td>Backend</td><td><code>server/src/graphql/resolvers/refundRequest.resolver.js</code> → <code>approveRefundRequest</code></td><td><strong>New:</strong> Before performing refund, (1) if <code>slot.status</code> is <code>&quot;completed&quot;</code> or <code>&quot;missed&quot;</code>, mark request rejected and throw. (2) If <code>slotEnd &lt;= new Date()</code>, mark request rejected and throw. Rejection reasons stored for admin/student.</td></tr><tr><td>Frontend</td><td><code>Frontend/src/pages/private/student-dashboard/bookingDetails.tsx</code></td><td>&quot;Request refund&quot; button disabled when <code>isSlotLessonPast</code> is true. Tooltip: <em>&quot;Refund cannot be requested after the lesson date has passed.&quot;</em></td></tr></tbody></table><hr><h2 id="_3-complete-checkout-incomplete-checkouts" tabindex="-1">3. Complete Checkout (Incomplete Checkouts) <a class="header-anchor" href="#_3-complete-checkout-incomplete-checkouts" aria-label="Permalink to &quot;3. Complete Checkout (Incomplete Checkouts)&quot;">​</a></h2><h3 id="rules-1" tabindex="-1">Rules <a class="header-anchor" href="#rules-1" aria-label="Permalink to &quot;Rules&quot;">​</a></h3><ul><li><p><strong>Pending booking (never finished checkout)</strong></p><ul><li>Student must <strong>not</strong> be able to complete checkout (create session / confirm payment) if the <strong>lesson date has passed</strong> (e.g. earliest slot start or any slot end in the past).</li></ul></li><li><p><strong>T-48 / booked lesson with incomplete payment (3DS or failed)</strong></p><ul><li>Student must <strong>not</strong> be able to complete payment for a slot if: <ul><li>The <strong>lesson date has passed</strong>, or</li><li>The instructor has marked the lesson <strong>completed</strong> or <strong>missed</strong>.</li></ul></li></ul></li></ul><h3 id="implementation-2" tabindex="-1">Implementation <a class="header-anchor" href="#implementation-2" aria-label="Permalink to &quot;Implementation&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Layer</th><th>Location</th><th>What was done</th></tr></thead><tbody><tr><td>Backend</td><td><code>studentBooking.resolver.js</code> → <code>createCheckoutSessionForPendingBooking</code></td><td>After computing <code>earliestSlotStart</code>, if <code>earliestSlotStart &lt;= now</code>, throw <em>&quot;Cannot complete checkout: lesson date has passed.&quot;</em></td></tr><tr><td>Backend</td><td><code>studentBooking.resolver.js</code> → <code>completeBookingFromCheckout</code></td><td>Before confirming payment, compute slot end times. If any slot’s end time is in the past, throw <em>&quot;Cannot complete checkout: lesson date has passed.&quot;</em></td></tr><tr><td>Backend</td><td><code>studentBooking.resolver.js</code> → <code>getT48ClientSecret</code></td><td>After ensuring slot needs payment (<code>requires_action</code> / <code>payment_failed</code>), added: (1) if <code>slot.status === &quot;completed&quot; || &quot;missed&quot;</code> throw; (2) if <code>slotEnd &lt;= new Date()</code> throw. Messages: <em>&quot;Cannot complete payment: this lesson was marked completed or missed.&quot;</em> / <em>&quot;Cannot complete payment: lesson date has passed.&quot;</em></td></tr><tr><td>Backend</td><td><code>studentBooking.resolver.js</code> → <code>completeT48SlotPayment</code></td><td>After resolving slot from PaymentIntent metadata, added same checks: block if slot is completed/missed or if lesson end time has passed.</td></tr><tr><td>Frontend</td><td><code>Frontend/src/pages/private/student-dashboard/bookLesson.tsx</code></td><td>Already filters T-48 “complete payment” list by <code>status === &quot;booked&quot; || &quot;confirmed&quot;</code> and <code>slotEnd &gt; now - 1hr</code>, so completed/missed and past slots are not shown. No change.</td></tr><tr><td>Frontend</td><td><code>Frontend/src/pages/private/student-dashboard/bookingDetails.tsx</code></td><td>&quot;Complete payment&quot; (3DS/retry) shown only when <code>canCompletePayment</code>: slot needs payment <strong>and</strong> <code>!isSlotLessonPast</code> <strong>and</strong> slot status is not completed/missed. If slot needs payment but cannot complete, an info message is shown instead of the button.</td></tr></tbody></table><hr><h2 id="_4-3ds-failed-payment-completion" tabindex="-1">4. 3DS / Failed Payment Completion <a class="header-anchor" href="#_4-3ds-failed-payment-completion" aria-label="Permalink to &quot;4. 3DS / Failed Payment Completion&quot;">​</a></h2><p>Same rules as <strong>§3</strong> for T-48: no completing 3DS or retry after lesson date has passed or lesson is marked completed/missed. Implemented in:</p><ul><li><strong>Backend:</strong> <code>getT48ClientSecret</code>, <code>completeT48SlotPayment</code> (see table in §3).</li><li><strong>Frontend:</strong> <code>bookingDetails</code> — <code>canCompletePayment</code> and the info message when payment is no longer allowed (see §3).</li></ul><hr><h2 id="_5-payout-no-double-payout-race-condition" tabindex="-1">5. Payout: No Double Payout (Race Condition) <a class="header-anchor" href="#_5-payout-no-double-payout-race-condition" aria-label="Permalink to &quot;5. Payout: No Double Payout (Race Condition)&quot;">​</a></h2><h3 id="rule-1" tabindex="-1">Rule <a class="header-anchor" href="#rule-1" aria-label="Permalink to &quot;Rule&quot;">​</a></h3><ul><li>A lesson that has already been paid out must <strong>not</strong> be paid out again. Concurrent runs of the payout job must not result in two payouts for the same slot.</li></ul><h3 id="implementation-3" tabindex="-1">Implementation <a class="header-anchor" href="#implementation-3" aria-label="Permalink to &quot;Implementation&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Layer</th><th>Location</th><th>What was done</th></tr></thead><tbody><tr><td>Backend</td><td><code>server/src/models/studentBooking.model.js</code></td><td>Extended <code>payoutStatus</code> enum with <code>&quot;processing&quot;</code> (in addition to <code>not_applicable</code>, <code>pending</code>, <code>completed</code>).</td></tr><tr><td>Backend</td><td><code>server/src/jobs/payoutJob.js</code></td><td>For each slot eligible for payout (<code>payoutStatus === &quot;pending&quot;</code>, <code>payoutEligibleAt &lt;= now</code>, etc.): (1) <strong>Atomic claim:</strong> <code>updateOne</code> with filter <code>slots._id</code>, <code>slots.payoutStatus === &quot;pending&quot;</code>, <code>slots.payoutEligibleAt &lt;= now</code>, and set <code>slots.$.payoutStatus = &quot;processing&quot;</code>. (2) Only if <code>modifiedCount === 1</code>, call Stripe <code>createManualPayoutForInstructor</code>, then set <code>payoutStatus = &quot;completed&quot;</code> and <code>payoutId</code>. (3) On Stripe failure (except test insufficient-funds), set slot back to <code>&quot;pending&quot;</code> so a later run can retry. This ensures only one process can “claim” a slot and perform the payout.</td></tr></tbody></table><hr><h2 id="_6-frontend-helpers-bookingdetails" tabindex="-1">6. Frontend Helpers (bookingDetails) <a class="header-anchor" href="#_6-frontend-helpers-bookingdetails" aria-label="Permalink to &quot;6. Frontend Helpers (bookingDetails)&quot;">​</a></h2><p>The following derived values were added or used in <code>bookingDetails.tsx</code> to support the above UI behavior:</p><table tabindex="0"><thead><tr><th>Variable</th><th>Meaning</th></tr></thead><tbody><tr><td><code>isLessonPast</code></td><td>Last slot of <code>selectedAvailability</code> (by end time) has passed. Used for multi-slot / current booking view.</td></tr><tr><td><code>isSlotLessonPast</code></td><td>The <strong>current</strong> slot’s lesson end time has passed. Based on <code>currentSlot.date</code> and <code>currentSlot.endTime</code> / <code>startTime</code>.</td></tr><tr><td><code>cannotCancel</code></td><td><code>isLessonPast</code> <strong>or</strong> current slot status is <code>completed</code> / <code>missed</code> / <code>refund</code>. Disables Cancel and Reschedule.</td></tr><tr><td><code>canCompletePayment</code></td><td>Slot needs payment (<code>requires_action</code> / <code>payment_failed</code>) <strong>and</strong> <code>!isSlotLessonPast</code> <strong>and</strong> slot status is not <code>completed</code> or <code>missed</code>. Controls visibility of &quot;Complete payment&quot; and the “no longer payable” message.</td></tr></tbody></table><p><code>currentSlot</code> is either the <code>slot</code> from location state (single-slot view from booked lessons) or the matching slot in <code>selectedAvailability</code>.</p><hr><h2 id="_7-file-reference" tabindex="-1">7. File Reference <a class="header-anchor" href="#_7-file-reference" aria-label="Permalink to &quot;7. File Reference&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Changes</th></tr></thead><tbody><tr><td><code>server/src/graphql/resolvers/studentBooking.resolver.js</code></td><td>Cancel: block completed/missed/refund. Checkout: block if lesson date passed in <code>createCheckoutSessionForPendingBooking</code> and <code>completeBookingFromCheckout</code>. T-48: block in <code>getT48ClientSecret</code> and <code>completeT48SlotPayment</code> if lesson past or completed/missed.</td></tr><tr><td><code>server/src/graphql/resolvers/refundRequest.resolver.js</code></td><td><code>approveRefundRequest</code>: reject if slot completed/missed or lesson date passed.</td></tr><tr><td><code>server/src/models/studentBooking.model.js</code></td><td><code>payoutStatus</code> enum: added <code>&quot;processing&quot;</code>.</td></tr><tr><td><code>server/src/jobs/payoutJob.js</code></td><td>Atomic claim (pending → processing) before Stripe payout; reset to pending on non–test failure.</td></tr><tr><td><code>Frontend/src/pages/private/student-dashboard/bookingDetails.tsx</code></td><td><code>isLessonPast</code>, <code>isSlotLessonPast</code>, <code>cannotCancel</code>, <code>canCompletePayment</code>; disable Cancel/Reschedule and Request refund when appropriate; show &quot;Complete payment&quot; only when allowed, else info message; tooltips.</td></tr></tbody></table><hr><p><em>Last updated: March 2025</em></p>',42)])])}const p=t(n,[["render",a]]);export{m as __pageData,p as default};
